create extension if not exists pgcrypto;
create table if not exists products(id uuid primary key default gen_random_uuid(),canonical_key text unique not null,title text not null,brand text,model text,category text,image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists market_listings(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,market text not null,external_id text,title text not null,url text,currency text not null,price numeric(14,2),condition text,availability text,observed_at timestamptz not null default now(),unique(product_id,market,external_id));
create table if not exists korean_listings(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,marketplace text not null,external_id text,title text not null,url text,price_krw numeric(14,0),seller_name text,observed_at timestamptz not null default now(),unique(product_id,marketplace,external_id));
create table if not exists price_history(id bigserial primary key,market_listing_id uuid references market_listings(id) on delete cascade,korean_listing_id uuid references korean_listings(id) on delete cascade,price numeric(14,2) not null,currency text not null,observed_at timestamptz not null default now(),check((market_listing_id is not null)<>(korean_listing_id is not null)));
create table if not exists exchange_rates(id bigserial primary key,base_currency text not null,quote_currency text not null,rate numeric(18,8) not null,observed_at timestamptz not null default now());
create table if not exists arbitrage_opportunities(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,source_listing_id uuid references market_listings(id) on delete set null,target_listing_id uuid references korean_listings(id) on delete set null,fx_rate numeric(18,8),shipping_krw numeric(14,0) default 0,fees_krw numeric(14,0) default 0,tax_krw numeric(14,0) default 0,other_cost_krw numeric(14,0) default 0,total_cost_krw numeric(14,0),selling_price_krw numeric(14,0),net_profit_krw numeric(14,0),roi_percent numeric(8,2),risk_level text,calculated_at timestamptz not null default now());
create table if not exists watchlists(id uuid primary key default gen_random_uuid(),user_id uuid,product_id uuid not null references products(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,product_id));
create table if not exists alert_rules(id uuid primary key default gen_random_uuid(),user_id uuid,product_id uuid references products(id) on delete cascade,min_roi_percent numeric(8,2),min_profit_krw numeric(14,0),max_source_price numeric(14,2),enabled boolean not null default true,created_at timestamptz not null default now());
create table if not exists alert_logs(id bigserial primary key,alert_rule_id uuid references alert_rules(id) on delete set null,channel text not null,status text not null,payload jsonb,sent_at timestamptz not null default now());
create index if not exists idx_market_listings_product on market_listings(product_id);create index if not exists idx_korean_listings_product on korean_listings(product_id);create index if not exists idx_price_history_observed on price_history(observed_at desc);create index if not exists idx_arbitrage_roi on arbitrage_opportunities(roi_percent desc);
alter table products enable row level security;create policy "public can read products" on products for select to anon,authenticated using(true);